/**
 * Optional per-invocation context threaded into `applyResultSideEffects` —
 * used ONLY by the `improvementDiff` branch (Lot 5, "Gate + proposal à
 * l'import"). `cmdImport`'s per-item loop always passes a real one; the two
 * judge-local replay call sites (`markersToday.pendingReplays`,
 * `buildImportResultItem`) never produce a `kind: 'improvementDiff'` item —
 * see their own docstrings — so they call `applyResultSideEffects(item)`
 * with NO second argument, and every field below degrades gracefully absent
 * a `ctx` (documented at each fallback site).
 */
interface ApplyResultSideEffectsCtx {
  /** `AAAA-MM-JJ` — the night `cmdImport` is processing (`date`, already
   *  validated against `ISO_DATE_RE`). Pinned as `createGatedProposal`'s
   *  `nightDate` AND reused for this function's own branch-name
   *  pre-computation (`proposalBranchName`) and diff-artifact filename, so
   *  all three agree byte-for-byte. Absent → `todayUtcDate()`. */
  nightDate?: string;
  /** The SAME night's full `results.results` array (`cmdImport`'s `results`
   *  variable) — scanned for `skillJobGrade` siblings of this item's skill to
   *  derive `fromJobs` (see `deriveImprovementDiffJustification`). Absent →
   *  `fromJobs` falls back to `[itemKey]` (never empty; zod requires min 1). */
  siblingResults?: ImportResultItem[];
}

/**
 * Derives `fromJobs`/`jobsSummary` for an `improvementDiff` item's gate. The
 * cloud never sends `fromJobs` directly for this kind (only `skill`/
 * `changedPaths`/`note` — see `docs/evals/results-contract.md`), so it is
 * RECONSTRUCTED from the same night's `skillJobGrade` results for the same
 * skill. Falls back to `[itemKey]` (the improvementDiff item's own key) when
 * none are found — `ImprovementProposalSchema.fromJobs` is `min(1)`, so this
 * function never returns an empty array.
 */
function deriveImprovementDiffJustification(
  skill: string,
  itemKey: string,
  siblingResults: ImportResultItem[] | undefined,
): { fromJobs: string[]; jobsSummary: string } {
  const matches: string[] = [];
  for (const s of siblingResults ?? []) {
    if (s.kind === 'skillJobGrade' && s.skill === skill && s.jobId && !matches.includes(s.jobId)) {
      matches.push(s.jobId);
    }
  }
  if (matches.length > 0) {
    return {
      fromJobs: matches,
      jobsSummary: `Justifié par ${matches.length} job(s) noté(s) cette nuit : ${matches.join(', ')}`,
    };
  }
  return {
    fromJobs: [itemKey],
    jobsSummary:
      'Aucun SkillJob gradé cette même nuit pour ce skill — item improvementDiff lui-même comme seule ' +
      `justification (${itemKey})`,
  };
}

/**
 * Readable SUMMARY built from `changedPaths`/`note` — NEVER a fabricated
 * unified diff. `docs/evals/results-contract.md` is explicit that the cloud
 * sends "changedPaths[] (la liste des fichiers touchés, pas un patch unifié
 * brut — l'import ne parse aucun diff)" for an `improvementDiff` result; this
 * function honors that limitation rather than pretending to reconstruct a
 * real patch.
 */
function buildImprovementDiffSummaryText(r: ImportResultItem): string {
  const paths = r.changedPaths ?? [];
  return [
    'Fichiers modifiés :',
    ...(paths.length > 0 ? paths.map((p) => `- ${p}`) : ['- (aucun chemin communiqué)']),
    '',
    `Note du round cloud : ${r.note ?? '(aucune)'}`,
  ].join('\n');
}

/**
 * Writes `createGatedProposal`'s `diffText` to a real file under
 * `reviewsDir()/proposals/` (`diffPath`) and a small placeholder sibling
 * (`backupPath`) — both are purely INFORMATIVE metadata traced on the
 * `ImprovementProposal` row: `apply.ts` never reads either path back (see
 * `CreateGatedProposalInput`'s own doc comment). No real backup content
 * exists yet at gate-creation time — the actual backup, if any, is produced
 * later by the application mechanism itself, not by this import step.
 */
async function writeImprovementDiffArtifacts(
  skill: string,
  nightDate: string,
  diffText: string,
): Promise<{ diffPath: string; backupPath: string }> {
  const base = `${slugify(skill)}-${nightDate}`;
  const diffPath = path.join(reviewsDir(), 'proposals', `${base}.diff`);
  const backupPath = path.join(reviewsDir(), 'proposals', `${base}.backup-placeholder`);
  await atomicWrite(diffPath, diffText);
  await atomicWrite(
    backupPath,
    'placeholder — aucun contenu de backup à la création de la gate ; apply.ts ne lit jamais ce fichier, ' +
      "c'est une trace informative pour un futur lecteur humain\n",
  );
  return { diffPath, backupPath };
}

