/**
 * Create a new ImprovementProposal. Enforces the mono-proposal invariant
 * (exigence #12): when the caller creates one with `state: 'proposed'`
 * (the default) and a `proposed` proposal already exists for the same
 * `skill`, throws `DuplicateProposedProposalError` instead of writing —
 * the caller should enrich the existing proposal's `fromJobs` via
 * `updateImprovementProposal` instead.
 */
export async function createImprovementProposal(
  input: CreateImprovementProposalInput,
): Promise<ImprovementProposal> {
  const state = input.state ?? 'proposed';
  if (state === 'proposed') {
    const existing = await listImprovementProposals({ skill: input.skill, state: ['proposed'] });
    if (existing.length > 0) {
      throw new DuplicateProposedProposalError(input.skill, existing[0].id);
    }
  }

  const now = new Date().toISOString();
  const id = input.id ?? genId('improvement');
  const proposal = ImprovementProposalSchema.parse({
    ...input,
    schemaVersion: 1,
    id,
    version: input.version ?? 1,
    state,
    updatedAt: now,
  });
  const filePath = improvementProposalPath(id);
  await atomicWrite(filePath, JSON.stringify(proposal, null, 2));
  const persisted = await readImprovementProposalFile(filePath);
  if (!persisted) throw new Error('Failed to re-read persisted improvement proposal');
  return persisted;
}

export async function getImprovementProposal(id: string): Promise<ImprovementProposal | null> {
  return readImprovementProposalFile(improvementProposalPath(id));
